.dark{--sx-r-card:12px;--sx-r-md:9px;--sx-r-btn:9px;--sx-card:inset 0 1px 0 rgb(255 255 255 / 0.035), 0 0 0 1px rgb(255 255 255 / 0.045), 0 1px 2px rgb(0 0 0 / 0.35), 0 10px 30px -12px rgb(0 0 0 / 0.55);--sx-pop:inset 0 1px 0 rgb(255 255 255 / 0.06), 0 0 0 1px rgb(255 255 255 / 0.08), 0 4px 12px -4px rgb(0 0 0 / 0.45), 0 18px 48px -12px rgb(0 0 0 / 0.6);--sx-edge:inset 0 1px 0 rgb(255 255 255 / 0.04);--sx-btn:none;--sx-pill:inset 0 1px 0 rgb(255 255 255 / 0.04), 0 0 0 1px rgb(255 255 255 / 0.05), 0 1px 2px rgb(0 0 0 / 0.35);--sx-accent:#f39a7f;--sx-accent-2:#dda759;--sx-accent-ink:#f39c81;--sx-accent-fill:#f2896b;--sx-accent-fg:#1b0d09;--sx-glow:color-mix(in srgb, #f39a7f calc(100% * var(--sx-glow-k)), transparent);--sx-rim-c:linear-gradient(to bottom right,#e3a939,#fe9473,#f68dc1);--sx-ambient:9%;--sx-tint:#f2896b42;--sx-ring:#e0795c9e;--sx-line:#fffcf91a;--sx-line-3:#fffcf929;--sx-fg:#efece9;--sx-card-bg:#1c1714;--sx-fg-2:#aba29d;--sx-fg-3:#9d9690;--sx-fg-4:#79726d;--sx-sunken:#171310;--sx-raised:#221d1a;--sx-hover:#fffcf90b;--sx-seg:inset 0 1px 0 rgb(255 255 255 / 0.06), 0 0 0 1px #fffcf91a, 0 1px 3px rgb(0 0 0 / 0.4);--sx-veil:rgb(0 0 0 / 0.36)}
