[data-workspace-area="conversation"]{background-image:var(--sx-actor),linear-gradient(transparent 30%,var(--sx-canvas) 82%),var(--sx-moon),var(--sx-sky-b),var(--sx-floor),radial-gradient(120% 55% at 50% -12%,color-mix(in srgb,var(--sx-accent) var(--sx-ambient),transparent),transparent 62%)!important;background-size:320px 170px,auto,160px 160px,auto,100% 150px,100% 100%!important;background-position:12% 6px,0 0,right 16px top 4px,0 0,bottom,0 0!important;background-repeat:no-repeat,no-repeat,no-repeat,repeat,no-repeat,no-repeat!important}
.dark [data-workspace-area="conversation"]::before{background:var(--sx-sky-a);-webkit-mask:linear-gradient(#000 25%,transparent 78%);mask:linear-gradient(#000 25%,transparent 78%);animation:sx-tw 8s var(--sx-inout) infinite alternate}
@keyframes sx-tw{from{opacity:1}to{opacity:.3}}
.dark [data-workspace-area="conversation"]::after{background:radial-gradient(70% 50% at 30% -6%,color-mix(in srgb,var(--sx-accent) 10%,transparent),transparent 70%),radial-gradient(60% 46% at 78% -4%,color-mix(in srgb,var(--sx-accent-2) 7%,transparent),transparent 70%);opacity:0}
:root:not(.dark) [data-workspace-area="conversation"]::before{content:none}
:root:not(.dark) [data-workspace-area="conversation"]::after{inset:-80px -40px auto;height:75%;background:radial-gradient(55% 60% at 72% 0%,rgb(255 170 110 / .3),transparent 70%),radial-gradient(45% 50% at 20% 0%,color-mix(in srgb,var(--sx-accent) 10%,transparent),transparent 70%);opacity:.75;animation:sx-dawn 26s var(--sx-inout) infinite alternate}
@keyframes sx-dawn{from{transform:translateY(-16px)}to{transform:translateY(18px) scale(1.06)}}
:root:has(.chat-markdown[data-streaming],.live-tool-shine) [data-workspace-area="conversation"]::after{opacity:1}
:root:has(h1 [data-draft-project-trigger]) [data-workspace-area="conversation"]{--sx-moon:none}
[data-slot="sidebar-inner"]{background-image:var(--sx-side-glow),var(--surface-grain,none)!important;background-size:100% 100%,var(--surface-grain-size,auto)!important;background-position:0 0,0 0!important;background-repeat:no-repeat,repeat!important}
.dark [data-slot="sidebar-inner"]::before{content:"";position:absolute;top:15%;left:64%;width:84px;height:1px;border-radius:1px;pointer-events:none;background:linear-gradient(90deg,#f7dcc4,transparent);rotate:-28deg;opacity:0;animation:sx-shoot 26s linear 5s infinite}
@keyframes sx-shoot{0%,95%{opacity:0;translate:0 0}95.5%{opacity:1}98.5%{opacity:0;translate:-130px 69px}100%{opacity:0}}
